// MySpace\MyS_Front\src\Api.js

import perfilData from "./data/perfilData";

// Simular delay de red
const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

// Obtener usuarios guardados en localStorage
const getUsuariosRegistrados = () => {
    try {
        const usuarios = localStorage.getItem("usuariosRegistrados");
        return usuarios ? JSON.parse(usuarios) : [...perfilData];
    } catch (error) {
        console.error("Error al leer usuarios:", error);
        return [...perfilData];
    }
};

// Guardar usuarios en localStorage
const saveUsuariosRegistrados = (usuarios) => {
    localStorage.setItem("usuariosRegistrados", JSON.stringify(usuarios));
};

// LOGIN - Simular llamada a API
export const login = async (correo, pass) => {
    console.log("=== LOGIN API ===");
    console.log("Correo:", correo);
    console.log("Pass:", pass);

    await delay(500); // Simular delay de red

    // Buscar en usuarios registrados (incluye perfilData inicial)
    const usuarios = getUsuariosRegistrados();
    console.log("Usuarios disponibles:", usuarios);

    const usuario = usuarios.find(u => 
        u.correo.toLowerCase() === correo.toLowerCase()
    );

    console.log("Usuario encontrado:", usuario);

    if (!usuario) {
        throw new Error("Correo no registrado");
    }

    if (usuario.password !== pass) {
        throw new Error("Contraseña incorrecta");
    }

    // Retornar estructura similar a backend
    return {
        success: true,
        message: "Login exitoso",
        usuario: {
            correo: usuario.correo,
            nombre: usuario.nombre,
            apellido_p: usuario.apellido_p || "",
            apellido_m: usuario.apellido_m || "",
            fecha_nacimiento: usuario.fecha_nacimiento || ""
        },
        perfil: {
            nom_usuario: usuario.nom_usuario || usuario.nombre,
            descripcion: usuario.descripcion || "",
            foto_perfil: usuario.imagen || "/user.svg"
        }
    };
};

// REGISTRO - Simular llamada a API
export const registro = async (userData) => {
    console.log("=== REGISTRO API ===");
    console.log("Datos recibidos:", userData);

    await delay(500); // Simular delay de red

    // Obtener usuarios existentes
    const usuarios = getUsuariosRegistrados();

    // Verificar si el correo ya existe
    const correoExiste = usuarios.find(u => 
        u.correo.toLowerCase() === userData.correo.toLowerCase()
    );

    if (correoExiste) {
        throw new Error(JSON.stringify({ correo: "Este correo ya está registrado" }));
    }

    // Verificar si el nombre de usuario ya existe
    const nomUsuarioExiste = usuarios.find(u => 
        u.nom_usuario === userData.nom_usuario
    );

    if (nomUsuarioExiste) {
        throw new Error(JSON.stringify({ nom_usuario: "Este nombre de usuario ya está en uso" }));
    }

    // Crear nuevo usuario
    const nuevoUsuario = {
        nombre: userData.nombre,
        apellido_p: userData.apellido_p,
        apellido_m: userData.apellido_m,
        correo: userData.correo,
        password: userData.contrasena,
        fecha_nacimiento: userData.fecha_nacimiento,
        nom_usuario: userData.nom_usuario,
        descripcion: userData.descripcion || "",
        imagen: userData.foto_perfil || "/user.svg"
    };

    // Agregar a la lista y guardar
    usuarios.push(nuevoUsuario);
    saveUsuariosRegistrados(usuarios);

    console.log("Usuario registrado:", nuevoUsuario);
    console.log("Total usuarios:", usuarios.length);

    // Retornar estructura similar a backend
    return {
        success: true,
        message: "Registro exitoso",
        usuario: {
            correo: nuevoUsuario.correo,
            nombre: nuevoUsuario.nombre,
            apellido_p: nuevoUsuario.apellido_p,
            apellido_m: nuevoUsuario.apellido_m,
            fecha_nacimiento: nuevoUsuario.fecha_nacimiento
        },
        perfil: {
            nom_usuario: nuevoUsuario.nom_usuario,
            descripcion: nuevoUsuario.descripcion,
            foto_perfil: nuevoUsuario.imagen
        }
    };
};

// OBTENER TODOS LOS USUARIOS (para debugging)
export const obtenerUsuarios = () => {
    return getUsuariosRegistrados();
};

// LIMPIAR USUARIOS (útil para testing)
export const limpiarUsuarios = () => {
    localStorage.removeItem("usuariosRegistrados");
    console.log("Usuarios limpiados, se usará perfilData por defecto");
};
